<?php
namespace App\Http\Controllers\Integrations;
use App\Http\Controllers\Controller; use App\Models\Integration\IntegrationInboundEvent; use App\Models\ProductVariant; use App\Services\Integrations\CatalogIntegrationPublisher; use App\Services\Integrations\WebsiteOrderInboundService; use Illuminate\Http\Request;
class AriyaSiteController extends Controller { public function storeOrder(Request $r, WebsiteOrderInboundService $s){$res=$s->handle($r->json()->all(),(string)$r->header('X-Ariya-Event-Id')); return response()->json($res['body'],$res['code']);} public function event(string $eventId){$e=IntegrationInboundEvent::where('event_id',$eventId)->first(); return $e?response()->json($e):response()->json(['ok'=>false,'status'=>'not_found'],404);} public function variants(Request $r, CatalogIntegrationPublisher $p){$q=ProductVariant::query()->where('is_active',true)->orderBy('id'); return response()->json(['data'=>$q->cursorPaginate(min(200,max(1,(int)$r->integer('limit',100))))->through(fn($v)=>$p->variantPayload($v))->items()]);} public function variant(string $externalId, CatalogIntegrationPublisher $p){$v=ProductVariant::where('variant_code',$externalId)->orWhere('variety_id',(int)$externalId)->firstOrFail(); return response()->json(['data'=>$p->variantPayload($v)]);} }
